function ms(clock: string): number {
  const [m, s] = clock.split(':').map(Number);
  return (m! * 60 + s!) * 1000;
}

export const CUES: SubtitleCue[] = LINES.map(([clock, text], i) => ({
  start: ms(clock),
  end: i + 1 < LINES.length ? ms(LINES[i + 1]![0]) : ms(clock) + 3000,
  text,
}));

/** The cue playing in every scene: こうやって直接塗るタイプの日焼け止め。 */
export const ACTIVE_INDEX = CUES.findIndex((c) => c.text.startsWith('こうやって直接'));
export const NOW_MS = CUES[ACTIVE_INDEX]!.start + 1200;

