const EXPLAIN_ANSWER = `**こうやって直接塗るタイプ** — "the kind you apply directly, like this."

- **こうやって** = "like this / this way", said while demonstrating. Very common when someone is showing an object on camera.
- **直接塗る** (ちょくせつ ぬる) — *to apply directly*. 塗る is the standard verb for spreading creams, paint, butter.
- **タイプ** turns the whole clause into a noun modifier: 「直接塗る**タイプ**の日焼け止め」 = "a sunscreen *of the apply-directly type*".

He contrasts it with the previous line (ベタベタするの嫌い): he dislikes sticky lotions, so he uses a **stick** sunscreen you rub straight onto the skin.`;

const SUMMARY_ANSWER = `A nomad who moved abroad with one backpack walks through everything he carries.

#### Toiletries (12:47–14:20)
- A **MUJI pouch** (a sacoche with the strap removed) holds toothpaste, a MUJI perfume case and chargers.
- Products he can't get locally (cleansing oil, shampoo) are refilled when he visits Japan.
- **Sunscreen:** he hates sticky lotion, so he uses a Korean **stick** type applied directly.
- **Reedle S300** — a microneedle serum he likes, though he wants the stronger 500/1000.
- An **all-in-one gel** replaces toner and moisturiser; 50 ml so it passes carry-on rules.

#### Electronics (14:21–)
- He carries only **one cable** for everything.`;

const FOLLOW_UP_ANSWER = `He says it at **13:55–13:57**: 「ただ300じゃ弱いんで500とか1000とか欲しいな」 — *"300 is a bit weak, so I'd like a 500 or 1000."* The number is the needle concentration, so higher = stronger.`;

export function answerFor(start: AssistantPortClientMessage): string {
  if (start.type === 'explain') return EXPLAIN_ANSWER;
  return start.request.history.length > 0 ? FOLLOW_UP_ANSWER : SUMMARY_ANSWER;
}

export const SUMMARY_FOLLOW_UP = 'Which Reedle strength does he want?';
